-- default.traces: 0 rows
-- 4. Views, materialized views, dictionaries (after all data, so an MV does not insert again)
CREATE VIEW default.analytics_observations
(
    `project_id` String,
    `type` LowCardinality(String),
    `hour` DateTime,
    `countObservations` UInt64,
    `hasLevel` UInt8,
    `hasProvidedModelName` UInt8,
    `hasProvidedUsageDetails` UInt8,
    `hasProvidedCostDetails` UInt8,
    `hasPromptName` UInt8
)
AS SELECT
    project_id,
    type,
    toStartOfHour(start_time) AS hour,
    uniq(id) AS countObservations,
    max(level != 'DEFAULT') AS hasLevel,
    max(provided_model_name IS NOT NULL) AS hasProvidedModelName,
    max(length(provided_usage_details) > 0) AS hasProvidedUsageDetails,
    max(length(provided_cost_details) > 0) AS hasProvidedCostDetails,
    max(prompt_name IS NOT NULL) AS hasPromptName
FROM default.observations
WHERE toStartOfHour(start_time) <= toStartOfHour(subtractHours(now(), 1))
GROUP BY
    project_id,
    type,
    hour;

CREATE VIEW default.analytics_scores
(
    `project_id` String,
    `hour` DateTime,
    `countScores` UInt64,
    `hasAnnotation` UInt8,
    `hasApi` UInt8,
    `hasEval` UInt8,
    `hasObservationScore` UInt8,
    `hasSessionScore` UInt8,
    `hasDatasetRunScore` UInt8,
    `hasBoolScore` UInt8,
    `hasNumericScore` UInt8,
    `hasCategoricalScore` UInt8,
    `hasComment` UInt8,
    `ingested_sdks` Map(String, UInt64)
)
AS SELECT
    project_id,
    toStartOfHour(timestamp) AS hour,
    uniq(id) AS countScores,
    max(source = 'ANNOTATION') AS hasAnnotation,
    max(source = 'API') AS hasApi,
    max(source = 'EVAL') AS hasEval,
    max(observation_id IS NOT NULL) AS hasObservationScore,
    max(session_id IS NOT NULL) AS hasSessionScore,
    max(dataset_run_id IS NOT NULL) AS hasDatasetRunScore,
    max(data_type = 'BOOLEAN') AS hasBoolScore,
    max(data_type = 'NUMERIC') AS hasNumericScore,
    max(data_type = 'CATEGORICAL') AS hasCategoricalScore,
    max(comment IS NOT NULL) AS hasComment,
    sumMap(map(concat(if(ingestion_sdk_name = '', 'unknown', ingestion_sdk_name), '@', if(ingestion_sdk_version = '', 'unknown', ingestion_sdk_version)), toUInt64(1))) AS ingested_sdks
FROM default.scores
WHERE toStartOfHour(timestamp) <= toStartOfHour(subtractHours(now(), 1))
GROUP BY
    project_id,
    hour;

CREATE VIEW default.analytics_traces
(
    `project_id` String,
    `hour` DateTime,
    `countTraces` UInt64,
    `hasUsers` UInt8,
    `hasSessions` UInt8,
    `hasEnvironments` UInt8,
    `hasTags` UInt8
)
AS SELECT
    project_id,
    toStartOfHour(timestamp) AS hour,
    uniq(id) AS countTraces,
    max(user_id IS NOT NULL) AS hasUsers,
    max(session_id IS NOT NULL) AS hasSessions,
    max(if(environment != 'default', 1, 0)) AS hasEnvironments,
    max(length(tags) > 0) AS hasTags
FROM default.traces
WHERE toStartOfHour(timestamp) <= toStartOfHour(subtractHours(now(), 1))
GROUP BY
    project_id,
    hour;

CREATE MATERIALIZED VIEW default.events_core_mv TO default.events_core
(
    `project_id` String,
    `trace_id` String,
    `span_id` String,
    `parent_span_id` String,
    `start_time` DateTime64(6),
    `end_time` Nullable(DateTime64(6)),
    `name` String,
    `type` LowCardinality(String),
    `environment` LowCardinality(String),
    `version` String,
    `release` String,
    `trace_name` String,
    `user_id` String,
    `session_id` String,
    `tags` Array(String),
    `level` LowCardinality(String),
    `status_message` String,
    `completion_start_time` Nullable(DateTime64(6)),
    `is_app_root` Bool,
    `bookmarked` Bool,
    `public` Bool,
    `prompt_id` String,
    `prompt_name` String,
    `prompt_version` Nullable(UInt16),
    `model_id` String,
    `provided_model_name` String,
    `model_parameters` String,
    `provided_usage_details` Map(LowCardinality(String), UInt64),
    `usage_details` Map(LowCardinality(String), UInt64),
    `provided_cost_details` Map(LowCardinality(String), Decimal(18, 12)),
    `cost_details` Map(LowCardinality(String), Decimal(18, 12)),
    `usage_pricing_tier_id` Nullable(String),
    `usage_pricing_tier_name` Nullable(String),
    `tool_definitions` Map(String, String),
    `tool_calls` Array(String),
    `tool_call_names` Array(String),
    `input` String,
    `output` String,
    `metadata_names` Array(String),
    `metadata_values` Array(String),
    `evaluator_id` String,
    `evaluation_rule_id` String,
    `evaluator_execution_is_test` Bool,
    `experiment_id` String,
    `experiment_name` String,
    `experiment_metadata_names` Array(String),
    `experiment_metadata_values` Array(String),
    `experiment_description` String,
    `experiment_dataset_id` String,
    `experiment_item_id` String,
    `experiment_item_version` Nullable(DateTime64(6)),
    `experiment_item_expected_output` String,
    `experiment_item_metadata_names` Array(String),
    `experiment_item_metadata_values` Array(String),
    `experiment_item_root_span_id` String,
    `source` LowCardinality(String),
    `service_name` String,
    `service_version` String,
    `scope_name` String,
    `scope_version` String,
    `telemetry_sdk_language` LowCardinality(String),
    `telemetry_sdk_name` String,
    `telemetry_sdk_version` String,
    `blob_storage_file_path` String,
    `event_bytes` UInt64,
    `created_at` DateTime64(6),
    `updated_at` DateTime64(6),
    `event_ts` DateTime64(6),
    `is_deleted` UInt8,
    `ingestion_api_key` String,
    `ingestion_sdk_name` LowCardinality(String),
    `ingestion_sdk_version` LowCardinality(String)
)
AS SELECT
    project_id,
    trace_id,
    span_id,
    parent_span_id,
    start_time,
    end_time,
    name,
    type,
    environment,
    version,
    release,
    trace_name,
    user_id,
    session_id,
    tags,
    level,
    status_message,
    completion_start_time,
    is_app_root,
    bookmarked,
    public,
    prompt_id,
    prompt_name,
    prompt_version,
    model_id,
    provided_model_name,
    model_parameters,
    provided_usage_details,
    usage_details,
    provided_cost_details,
    cost_details,
    usage_pricing_tier_id,
    usage_pricing_tier_name,
    tool_definitions,
    tool_calls,
    tool_call_names,
    leftUTF8(input, 200) AS input,
    leftUTF8(output, 200) AS output,
    metadata_names,
    arrayMap(v -> leftUTF8(v, 200), metadata_values) AS metadata_values,
    evaluator_id,
    evaluation_rule_id,
    evaluator_execution_is_test,
    experiment_id,
    experiment_name,
    experiment_metadata_names,
    experiment_metadata_values,
    experiment_description,
    experiment_dataset_id,
    experiment_item_id,
    experiment_item_version,
    experiment_item_expected_output,
    experiment_item_metadata_names,
    experiment_item_metadata_values,
    experiment_item_root_span_id,
    source,
    service_name,
    service_version,
    scope_name,
    scope_version,
    telemetry_sdk_language,
    telemetry_sdk_name,
    telemetry_sdk_version,
    blob_storage_file_path,
    event_bytes,
    created_at,
    updated_at,
    event_ts,
    is_deleted,
    ingestion_api_key,
    ingestion_sdk_name,
    ingestion_sdk_version
FROM default.events_full
SETTINGS enable_full_text_index = 1;
